CREATE   PROCEDURE [synapse_ce].[usp_Insert_subject]
AS
BEGIN
	INSERT INTO [synapse_ce].[subject]
	(
		[createdby],
		[createdby_entitytype],
		[createdbyexternalparty],
		[createdbyexternalparty_entitytype],
		[createdbyexternalpartyname],
		[createdbyexternalpartyyominame],
		[createdbyname],
		[createdbyyominame],
		[createdon],
		[createdonbehalfby],
		[createdonbehalfby_entitytype],
		[createdonbehalfbyname],
		[createdonbehalfbyyominame],
		[description],
		[featuremask],
		[Id],
		[importsequencenumber],
		[modifiedby],
		[modifiedby_entitytype],
		[modifiedbyexternalparty],
		[modifiedbyexternalparty_entitytype],
		[modifiedbyexternalpartyname],
		[modifiedbyexternalpartyyominame],
		[modifiedbyname],
		[modifiedbyyominame],
		[modifiedon],
		[modifiedonbehalfby],
		[modifiedonbehalfby_entitytype],
		[modifiedonbehalfbyname],
		[modifiedonbehalfbyyominame],
		[organizationid],
		[organizationid_entitytype],
		[organizationidname],
		[overriddencreatedon],
		[parentsubject],
		[parentsubject_entitytype],
		[parentsubjectname],
		[SinkCreatedOn],
		[SinkModifiedOn],
		[subjectid],
		[title],
		[versionnumber]
	)
	SELECT 
		stg.[createdby],
		stg.[createdby_entitytype],
		stg.[createdbyexternalparty],
		stg.[createdbyexternalparty_entitytype],
		stg.[createdbyexternalpartyname],
		stg.[createdbyexternalpartyyominame],
		stg.[createdbyname],
		stg.[createdbyyominame],
		stg.[createdon],
		stg.[createdonbehalfby],
		stg.[createdonbehalfby_entitytype],
		stg.[createdonbehalfbyname],
		stg.[createdonbehalfbyyominame],
		stg.[description],
		stg.[featuremask],
		stg.[Id],
		stg.[importsequencenumber],
		stg.[modifiedby],
		stg.[modifiedby_entitytype],
		stg.[modifiedbyexternalparty],
		stg.[modifiedbyexternalparty_entitytype],
		stg.[modifiedbyexternalpartyname],
		stg.[modifiedbyexternalpartyyominame],
		stg.[modifiedbyname],
		stg.[modifiedbyyominame],
		stg.[modifiedon],
		stg.[modifiedonbehalfby],
		stg.[modifiedonbehalfby_entitytype],
		stg.[modifiedonbehalfbyname],
		stg.[modifiedonbehalfbyyominame],
		stg.[organizationid],
		stg.[organizationid_entitytype],
		stg.[organizationidname],
		stg.[overriddencreatedon],
		stg.[parentsubject],
		stg.[parentsubject_entitytype],
		stg.[parentsubjectname],
		stg.[SinkCreatedOn],
		stg.[SinkModifiedOn],
		stg.[subjectid],
		stg.[title],
		stg.[versionnumber]	
	FROM [staging_ce].[subject] stg
		LEFT JOIN [synapse_ce].[subject] tgt
			ON tgt.[id] = stg.[id]
	WHERE tgt.[id] IS NULL
END
